namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly List<Notification> _notifications;
    private int _nextId;
    private readonly Lock _lock = new();

    public NotificationService()
    {
        _notifications =
        [
            new(1, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)),
            new(2, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)),
            new(3, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-5)),
        ];
        _nextId = 4;
    }

    public List<Notification> GetNotifications()
    {
        lock (_lock)
        {
            return [.. _notifications.OrderByDescending(n => n.Timestamp)];
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// Randomly generates a new notification ~1 in 3 calls to simulate activity.
    /// </summary>
    public List<Notification> GetNotificationsSince(DateTime since)
    {
        lock (_lock)
        {
            if (Random.Shared.Next(3) == 0)
            {
                var id = _nextId++;
                _notifications.Add(new Notification(
                    id,
                    $"New event #{id} just happened.",
                    DateTime.UtcNow));
            }

            return [.. _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)];
        }
    }
}

