@page "/notifications"
@using BlazorApp.Services
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private DateTime _lastChecked;

    // Runs during both prerender and interactive — loads initial data for SSR.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetNotifications();
        _lastChecked = _notifications.Count > 0
            ? _notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    // Called only once after the component is interactive in the browser.
    // On the prerender pass this fires but the circuit is not yet live,
    // so we gate on the second (interactive) call.
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        // firstRender is true exactly once per circuit — which is the
        // interactive activation (prerender doesn't establish a circuit).
        _cts = new CancellationTokenSource();
        _ = PollForNotificationsAsync(_cts.Token);
        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }

            var newer = NotificationService.GetNotificationsSince(_lastChecked);
            if (newer.Count > 0)
            {
                _notifications.InsertRange(0, newer);
                _lastChecked = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

